// SPDX-License-Identifier: MIT
pragma solidity >=0.7.0 <0.9.0;

contract OddEven {

    function CheckOddEven(uint number) public pure returns(uint, string memory) {
        if (number % 2 == 0) {
            return (number, "Even");
        } else {
            return (number, "Odd");
        }
    }
}

